<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\SubscriptionEligibilityService;use App\Support\Url;Auth::requirePermission('SUBSCRIPTION_REVIEW_QUEUE_VIEW');$rows=SubscriptionEligibilityService::operationsQueue();$pageTitle='Subscription Requests';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>Subscription requests</h1><p>Carrier plans awaiting offline payment confirmation. Confirmation activates immediately.</p></div><span class="badge"><?=h(count($rows))?> pending</span></div><div class="card table-wrap"><table><thead><tr><th>Reference</th><th>Carrier</th><th>Plan</th><th>Requested UTC</th><th></th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=h($r['subscription_ref'])?></td><td><?=h($r['owner_company_name']?:$r['owner_user_name'])?></td><td><?=h($r['plan_name'])?></td><td><?=h($r['requested_at'])?></td><td><a href="<?=h(Url::to('operations/subscription-review.php?id='.$r['subscription_id']))?>">Confirm payment</a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5" class="muted">No pending subscription requests.</td></tr><?php endif;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';
